      "arFull": "اَلَمْ تَرَ اَنَّاۤ اَرْسَلْنَا الشَّیٰطِیْنَ عَلَی الْكٰفِرِیْنَ تَؤُزُّهُمْ اَزًّا ۟ۙ",
