      "footnotesUr": "[1] یعنی دنیا میں لوگوں کے دلوں میں اس کی نیکی اور پارسائی کی وجہ سے محبت پیدا کر دے گا، جیسا کہ حدیث میں آتا ہے ”جب اللہ تعالٰی کسی (نیک) بندے کو اپنا محبوب بنا لیتا ہے تو اللہ جبرائیل (عليه السلام) کو کہتا ہے، میں فلاں بندے سے محبت کرتا ہوں تو بھی اس سے محبت کر۔ پس جبرائیل (عليه السلام) بھی اس سے محبت کرنی شروع کر دیتے ہیں پھر جبرائیل (عليه السلام) آسمان میں منادی کرتے ہیں کہ اللہ تعالٰی فلاں آدمی سے محبت کرتا ہے، پس تمام آسمان والے بھی اس سے محبت کرنے لگتے ہیں، پھر زمین میں اس کے لئے قبولیت اور پذیرائی رکھ دی جاتی ہے“۔ (صحيح بخاري، كتاب الأدب، باب المقت من الله تعالى)۔",
